                        $('[id*=cmdIniciarAtividade]').removeClass('invisivel');

                        $('[id*=cmdPausarAtividade]').addClass('invisivel');
                        $('[id*=cmdFinalizarAtividade]').addClass('invisivel');
                        $('[id*=cmdExcluirAtividade]').addClass('invisivel');
                        $('[id*=cmdAtividadeImpedida]').addClass('invisivel');

