                    $('[id*=txtHoras_Apontamento]').val(apontamento.nHoras.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
                    $('[id*=txtMotivo_Apontamento]').val('');
                    tinymce.get('cphCorpo_txtObservacao_Apontamento').setContent(apontamento.sObservacao);
                    $('[id*=txtData_Apontamento]').val(FormatarDataHora(apontamento.dtApontamento, true, true, false));

