    function ValidarAlteracaoStatus(atividade) {
        try {
            if (!ValidaData(atividade.dtInicial_Previsao) || !ValidaData(atividade.dtFinal_Previsao) || !atividade.nHoras_Previsao) {
                throw new Error('é necessário que ela possua as Horas e Datas Inicial e Final Previstas!');
            } else if (!atividade.sDscTitulo || !atividade.sDscDescricao) {
                throw new Error('é necessário que ela possua o Título e a Descrição preenchidos!');
            } else if (!list_Atividades_UsuariosAssociados.hasOwnProperty(atividade.idAtividade) || !list_Atividades_UsuariosAssociados[atividade.idAtividade].length) {
                throw new Error('é necessário que ela possua ao menos um Usuário Associado!');
            }
        } catch (error) {
            ExibirMensagem_Validacao(4, 2, 'Para Iniciar a Atividade, ' + error.message, true);
            $('#modalEditarAtividade').modal('show');
            return false;
        }

        return true;
    }

    function SomarValores_Lista(list, sCampo) {
        return list.reduce((acc, item) => acc + (parseFloat(item[sCampo]) || 0), 0);
    }

    function ValidarUsuarioAssociado(idAtividade, idUsuario) {
        let um = list_Atividades_UsuariosAssociados.hasOwnProperty(idAtividade);
        let dois = Array.isArray(list_Atividades_UsuariosAssociados[idAtividade]);
        let tres = list_Atividades_UsuariosAssociados[idAtividade].includes(String(idUsuario));
        return um && dois && tres;
    }

    function ValidarDados(titulo, descricao, horas, bMsg) {
        let bValidado = true;
        let sErro = '';

        if (!titulo || !titulo.length) {
            sErro = 'É necessário preencher o Título do Projeto!';
        } else if (!descricao || !descricao.length) {
            sErro = 'É necessário preencher a Descrição do Projeto!';
        } else if (!horas) {
            sErro = 'É necessário preencher as Horas Previstas do Projeto!';
        } else if (!idEmpresa) {
            sErro = 'É necessário selecionar a Empresa do Projeto!';
        } else if (!ValidaObjeto(list_Projetos_Administradores)) {
            sErro = 'É necessário adicionar ao menos um Administrador ao Projeto!';
        }

        if (sErro && sErro.length) {
            bValidado = false;
            if (bMsg) throw new Error(sErro);
        }

        return bValidado;
    }

    async function SalvarDados(e) {
        e.preventDefault();
        $('[id*=div_Loading]').show();
        $('[id*=div_img]').show();

        EsconderMensagens(0);

        try {
            const titulo = $('[id*=txtsTitulo]').val();
            const descricao = $('[id*=txtsDescricao').val();
            const horas = $(txtnHoras_Previsao).val();

            if (ValidarDados(titulo, descricao, parseFloat(horas.replace('.', '').replace(',', '.')) || 0)) {
                const response = await $.ajax({
                    url: "/App/Paginas/Atividades/Projetos_Detalhe.aspx/Post_SalvarDados",
                    data: JSON.stringify({
                        idProjeto: idProjeto,
                        idEmpresa: idEmpresa,
                        idUsuario: idUsuario,
                        deptos: list_Projetos_Deptos,
                        titulo: titulo,
                        descricao: descricao,
                        horas: horas,
                        adms: list_Projetos_Administradores,
                        membros: list_Projetos_Membros,
                        atividades: list_Atividades,
                        usuariosAssociados: list_Atividades_UsuariosAssociados,
                        apontamentos: list_Apontamentos,
                        apontamentos_Historico: list_Apontamentos_Historico
                    }),
                    type: 'POST',
                    dataType: 'json',
                    contentType: 'application/json; charset=utf-8'
                });

                if (response && response.d) {
                    const bSucesso = response.d.bSucesso;
                    const sMensagem = response.d.sMensagem;

                    if (bSucesso) {
                        idProjeto = parseInt(response.d.idProjeto) || idProjeto;
                        RecarregarPagina(1);
                    } else {
                        throw new Error(sMensagem);
                    }
                }
            }
        } catch (error) {
            ExibirMensagem_Validacao(1, 2, '<b>Erro: </b>Houve um erro ao Salvar as informações do Projeto!' + RetornaMensagem_Erro(error), true);
        }

        setTimeout(function () {
            $('[id*=div_Loading]').hide();
            $('[id*=div_img]').hide();
        }, 50);
    }

    function RecarregarPagina(msg) {
        $(location).attr('href', `/App/Paginas/Atividades/Projetos_Detalhe.aspx?id=${idProjeto}&msg=${msg}`);
    }

    function ValidarArrays(arr1, arr2) {
        if (arr1.length !== arr2.length) return false;

        const sorted1 = [...arr1].sort();
        const sorted2 = [...arr2].sort();

        return sorted1.every((val, i) => val === sorted2[i]);
    }

    function ConverterData(data) {
        if (!data) return null;
        return new Date(parseInt(data.replace(/\/Date\((\d+)\)\//, "$1"), 10));
    }

    function CalculaDataFinal(dataInicial, horas) {
        const resultado = new Date(dataInicial);
        let horasRestantes = horas;

        while (horasRestantes > 0) {
            const diaSemana = resultado.getDay();

            if (diaSemana === 0 || diaSemana === 6) { // 0 = domingo, 6 = sábado
                resultado.setDate(resultado.getDate() + (!diaSemana ? 1 : 2)); // Vai para segunda
                resultado.setHours(8, 0, 0, 0);
                continue;
            }

            const horaInicio = 8;
            const horaAlmocoInicio = 12;
            const horaAlmocoFim = 13;
            const horaFim = diaSemana === 5 ? 17 : 18;
            let horaAtual = resultado.getHours() + resultado.getMinutes() / 60;

            // Se antes do expediente, ajusta para 8h
            if (horaAtual < horaInicio) {
                resultado.setHours(horaInicio, 0, 0, 0);
                horaAtual = horaInicio;
            }

            // Se está no horário de almoço, pula para 13h
            if (horaAtual >= horaAlmocoInicio && horaAtual < horaAlmocoFim) {
                resultado.setHours(horaAlmocoFim, 0, 0, 0);
                horaAtual = horaAlmocoFim;
            }

            // Se já passou do expediente, passa para o próximo dia
            if (horaAtual >= horaFim) {
                resultado.setDate(resultado.getDate() + 1);
                resultado.setHours(8, 0, 0, 0);
                continue;
            }

            // Calcula tempo restante hoje, descontando horário de almoço se ainda não passou
            let horaLimiteHoje = horaFim;
            let bloqueioAlmoco = 0;
            if (horaAtual < horaAlmocoInicio && horaFim > horaAlmocoFim) {
                bloqueioAlmoco = 1;
            }

            let horasDisponiveisHoje = horaLimiteHoje - horaAtual - bloqueioAlmoco;
            if (horasRestantes <= horasDisponiveisHoje) {
                let fim = horaAtual + horasRestantes;

                // Se atravessa o horário de almoço, adiciona mais 1h
                if (horaAtual < horaAlmocoInicio && fim > horaAlmocoInicio) {
                    fim += 1;
                }

                const horasParaAdicionar = fim - horaAtual;
                resultado.setTime(resultado.getTime() + horasParaAdicionar * 60 * 60 * 1000);
                return resultado;
            } else {
                const horasParaAvancar = horasDisponiveisHoje + bloqueioAlmoco;
                resultado.setTime(resultado.getTime() + horasParaAvancar * 60 * 60 * 1000);
                horasRestantes -= horasDisponiveisHoje;

                resultado.setDate(resultado.getDate() + 1);
                resultado.setHours(8, 0, 0, 0);
            }
        }

        return resultado;
    }

    function AtualizaDatas_Master(atividade) {
        if (atividade && atividade.idAtividadePai > 0) {
            const atividadePai = list_Atividades.find(a => a.idAtividade == atividade.idAtividadePai);

            if (atividadePai) {
                const list = list_Atividades.filter(a => a.idAtividadePai == atividadePai.idAtividade);
                const nHoras_Previsao = parseFloat(SomarValores_Lista(list, 'nHoras_Previsao')) || 0;
                const dtInicial_Previsao = new Date(Math.min(...list.map(a => a.dtInicial_Previsao).filter(ValidaData).map(d => new Date(d))));
                const dtInicial = new Date(Math.min(...list.map(a => a.dtInicial).filter(ValidaData).map(d => new Date(d))));
                const dtFinal_Previsao = new Date(Math.max(...list.map(a => a.dtFinal_Previsao).filter(ValidaData).map(d => new Date(d))));
                const dtFinal = new Date(Math.max(...list.map(a => a.dtFinal).filter(ValidaData).map(d => new Date(d))));

                atividadePai.nHoras_Previsao = nHoras_Previsao;
                atividadePai.dtInicial_Previsao = ValidaData(dtInicial_Previsao) ? dtInicial_Previsao : atividadePai.dtInicial_Previsao;
                atividadePai.dtInicial = ValidaData(dtInicial) ? dtInicial : atividadePai.dtInicial;
                atividadePai.dtFinal_Previsao = ValidaData(dtFinal_Previsao) ? dtFinal_Previsao : atividadePai.dtFinal_Previsao;
                atividadePai.dtFinal = ValidaData(dtFinal) ? dtFinal : atividadePai.dtFinal;
            }
        }
    }

    function CalculaHoras_ApontamentoFinal(atividade) {
        if (!atividade) return 0;

        const apontamentos = list_Apontamentos.filter(a => a.idAtividade == atividade.idAtividade && a.idTipo == 4);
        let inicio = null;
        const fim = new Date();

        if (apontamentos.length > 0) {
            inicio = apontamentos.reduce((maisRecente, atual) => {
                const dataAtual = new Date(atual.dtApontamento);
                return dataAtual > maisRecente ? dataAtual : maisRecente;
            }, new Date(0));
        } else {
            inicio = new Date(atividade.dtInicial);
        }

        let totalHoras = 0;
        const HORA_INICIO = 8;
        const HORA_ALMOCO_INICIO = 12;
        const HORA_ALMOCO_FIM = 13;
        const HORA_FIM_PADRAO = 18;
        const HORA_FIM_SEXTA = 17;
        const MS_POR_HORA = 60 * 60 * 1000;

        let atual = new Date(inicio);

        while (atual < fim) {
            const diaSemana = atual.getDay();

            // Pula fim de semana
            if (diaSemana === 0 || diaSemana === 6) {
                atual.setDate(atual.getDate() + 1);
                atual.setHours(HORA_INICIO, 0, 0, 0);
                continue;
            }

            const horaFimDia = (diaSemana === 5 ? HORA_FIM_SEXTA : HORA_FIM_PADRAO);

            // Define blocos de trabalho válidos: manhã e tarde
            const blocoManhaInicio = new Date(atual);
            blocoManhaInicio.setHours(HORA_INICIO, 0, 0, 0);
            const blocoManhaFim = new Date(atual);
            blocoManhaFim.setHours(HORA_ALMOCO_INICIO, 0, 0, 0);

            const blocoTardeInicio = new Date(atual);
            blocoTardeInicio.setHours(HORA_ALMOCO_FIM, 0, 0, 0);
            const blocoTardeFim = new Date(atual);
            blocoTardeFim.setHours(horaFimDia, 0, 0, 0);

            const inicioManha = new Date(Math.max(atual, blocoManhaInicio));
            const fimManha = new Date(Math.min(fim, blocoManhaFim));
            if (fimManha > inicioManha) {
                totalHoras += (fimManha - inicioManha) / MS_POR_HORA;
            }

            const inicioTarde = new Date(Math.max(atual, blocoTardeInicio));
            const fimTarde = new Date(Math.min(fim, blocoTardeFim));
            if (fimTarde > inicioTarde) {
                totalHoras += (fimTarde - inicioTarde) / MS_POR_HORA;
            }

            // Avança para o próximo dia útil às 8h
            atual.setDate(atual.getDate() + 1);
            atual.setHours(HORA_INICIO, 0, 0, 0);
        }

        return parseFloat(totalHoras) || 0;
    }

    function MantemComposicao_Aberta() {
        if (list_Composicao && list_Composicao.length > 0) {
            list_Composicao.forEach(c => {
                gvAtividades.find(`.composicaoLinha[data-div-id='${c}']`).each(function () {
                    $(this).trigger('click');
                });
            });
        }
    }

    function ValidaObjeto(obj) {
        return obj != null && Object.keys(obj).length > 0;
    }

    async function EditarAtividade(idAtividade) {
        const titulo = $('[id*=txtTitulo_EditarAtividade]').val();
        const descricao = $('[id*=txtDescricao_EditarAtividade]').val();
        const dtInicial = new Date($('[id*=txtdtInicial_Prevista_EditarAtividade]').val()) || null;
        const dtFinal = new Date($('[id*=txtdtFinal_Prevista_EditarAtividade]').val()) || null;

        if (!titulo) {
            throw new Error('O Título da Atividade é obrigatório!');
        } else if (!descricao) {
            throw new Error('A Descrição da Atividade é obrigatória!');
        } else if (ValidaData(dtInicial) && ValidaData(dtFinal) ? dtInicial > dtFinal : false) {
            throw new Error('A Data Inicial não pode ser maior que a Data Final!');
        } else {
            const atividade = list_Atividades.find(a => a.idAtividade == idAtividade);
            const bMaster = atividade.bAtividadePai;

            if (atividade) {
                if (!bMaster && (!lstUsuarios_EditarAtividade.val() || !lstUsuarios_EditarAtividade.val().length)) {
                    throw new Error('É obrigatório existir ao menos um Usuário Associado à Atividade!');
                }

                const nHoras = parseFloat($('[id*=txtHoras_EditarAtividade]').val().replace('.', '').replace(',', '.')) || null;
                let dataInicial_Diferente = false;
                let dataFinal_Diferente = false;
                let obs = '';

                if (ValidaData(atividade.dtInicial_Previsao) && ValidaData(dtInicial) && atividade.dtInicial_Previsao.getTime() != dtInicial.getTime()) dataInicial_Diferente = true;
                if ((ValidaData(atividade.dtInicial_Previsao) && !ValidaData(dtInicial)) || (!ValidaData(atividade.dtInicial_Previsao) && ValidaData(dtInicial))) dataInicial_Diferente = true;

                if (ValidaData(atividade.dtFinal_Previsao) && ValidaData(dtFinal) && atividade.dtFinal_Previsao.getTime() != dtFinal.getTime()) dataFinal_Diferente = true;
                if ((ValidaData(atividade.dtFinal_Previsao) && !ValidaData(dtFinal)) || (!ValidaData(atividade.dtFinal_Previsao) && ValidaData(dtFinal))) dataFinal_Diferente = true;

                obs += `${atividade.sDscTitulo != titulo ? `<br /> - Título alterado de <span class="infoAlterada">${atividade.sDscTitulo || '__'}</span> para <span class="infoNova">${titulo || '__'}</span>` : ''}
                            ${atividade.sDscDescricao != descricao ? `<br /> - Descrição alterada de <span class="infoAlterada">${atividade.sDscDescricao || '__'}</span> para <span class="infoNova">${descricao || '__'}</span>` : ''}`;

                if (!bMaster) {
                    const associados = list_Atividades_UsuariosAssociados[String(atividade.idAtividade)];
                    const editarAssociados = lstUsuarios_EditarAtividade.val();

                    if (!ValidarArrays(associados, editarAssociados)) {
                        const setOriginal = new Set(associados.map(String));
                        const setAtual = new Set(editarAssociados.map(String));
                        const removidos = [...setOriginal].filter(id => !setAtual.has(id));
                        const adicionados = [...setAtual].filter(id => !setOriginal.has(id));
                        let htmlRemovidos = '';
                        let htmlAdicionados = '';

                        removidos.forEach(id => {
                            htmlRemovidos += `<li>${list_Projetos_Administradores.hasOwnProperty(id) ? list_Projetos_Administradores[id] : list_Projetos_Membros[id]}</li>`;
                        });

                        adicionados.forEach(id => {
                            htmlAdicionados += `<li>${list_Projetos_Administradores.hasOwnProperty(id) ? list_Projetos_Administradores[id] : list_Projetos_Membros[id]}</li>`;
                        });

                        obs += `<br /> - Usuários Associados alterados!<br />${htmlRemovidos ? '<span class="infoAlterada"> --- Usuários removidos:</span><ul class="infoAlterada">' + htmlRemovidos + '</ul>' : ''}${htmlAdicionados ? '<span class="infoNova"> --- Usuários adicionados:</span><ul class="infoNova">' + htmlAdicionados + '</ul>' : ''}</ul>`;
                        list_Atividades_UsuariosAssociados[String(atividade.idAtividade)] = editarAssociados;
                    }

                    obs += `${atividade.nHoras_Previsao != nHoras ? `<br /> - Horas Previstas alteradas de <span class="infoAlterada">${atividade.nHoras_Previsao || '__'}</span> para <span class="infoNova">${nHoras || '__'}</span>` : ''}`
                    obs += `${dataInicial_Diferente ? `<br /> - Data Inicial Prevista alterada de <span class="infoAlterada">${FormatarDataHora(atividade.dtInicial_Previsao, true, false) || '__'}</span> para <span class="infoNova">${FormatarDataHora(dtInicial, true, false) || '__'}</span>` : ''}`;
                    obs += `${dataFinal_Diferente ? `<br /> - Data Final Prevista alterada de <span class="infoAlterada">${FormatarDataHora(atividade.dtFinal_Previsao, true, false) || '__'}</span> para <span class="infoNova">${FormatarDataHora(dtFinal, true, false) || '__'}</span>` : ''}`;

                    atividade.nHoras_Previsao = nHoras;
                    atividade.dtInicial_Previsao = dtInicial;
                    atividade.dtFinal_Previsao = dtFinal;

                    if (atividade.idAtividadePai > 0)
                        AtualizaDatas_Master(atividade);
                }

                atividade.sDscTitulo = titulo;
                atividade.sDscDescricao = descricao;

                if (!bMaster && obs && obs.length) {
                    let apontamento = {
                        idApontamento: GerarNovoID(list_Apontamentos, 2),
                        idAtividade: atividade.idAtividade,
                        idUsuario: idUsuario,
                        idTipo: 2,
                        sObservacao: `Informações da Atividade alteradas!${obs}`,
                        nHoras: 0,
                        dtApontamento: new Date(),
                        sDscUsuario: sDscUsuario,
                        bSalva: true // true
                    };

                    list_Apontamentos.push(apontamento);
                }

                ExibirMensagem_Validacao(3, 1, 'Atividade alterada com sucesso!', true);
                gvAtividades_DataBind();
                $('#modalEditarAtividade').modal('hide');
            } else {
                throw new Error('Atividade não encontrada!');
            }
        }
    }

