    gvAtividades.off('click').on('click', '.composicaoLinha', function (e) {
        e.preventDefault();
        const $this = $(this);
        const divId = $this.data('div-id');
        const current = $('#' + divId).css('display');
        if (current == 'none') {
            $('#' + divId).show('slow');
            $this.find('i').removeClass('fa fa-plus').addClass('fa fa-minus');

            const composicao = list_Composicao.findIndex(c => c == divId);
            if (composicao === -1) list_Composicao.push(divId);
        } else {
            $('#' + divId).hide('slow');
            $this.find('i').removeClass('fa fa-minus').addClass('fa fa-plus');

            const composicao = list_Composicao.findIndex(c => c == divId);
            if (composicao !== -1) list_Composicao.splice(composicao, 1);
        }
    });

